class UmrahScreen extends StatelessWidget{const UmrahScreen({super.key});@override Widget build(BuildContext c){final st=AppScope.of(c),s=umrahSteps[st.step];return SafeArea(child:Column(children:[Container(color:AppColors.green,padding:const EdgeInsets.all(14),width:double.infinity,child:const Text('دليل العمرة',style:TextStyle(color:Colors.white,fontSize:19,fontWeight:FontWeight.w800))),SizedBox(height:72,child:ListView.separated(reverse:true,padding:const EdgeInsets.all(8),scrollDirection:Axis.horizontal,itemCount:umrahSteps.length,separatorBuilder:(_,__)=>const SizedBox(width:8),itemBuilder:(c,i)=>ChoiceChip(selected:i==st.step,label:Text('${st.done.contains(i)?'✓':i+1} ${umrahSteps[i].title}'),onSelected:(_)=>st.change(()=>st.step=i)))),Expanded(child:ListView(padding:const EdgeInsets.all(14),children:[AppCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(mainAxisAlignment:MainAxisAlignment.spaceBetween,children:[Text('${s.icon} ${s.title}',style:const TextStyle(fontSize:22,fontWeight:FontWeight.w800)),Text('الخطوة ${st.step+1} من 7')]),const SizedBox(height:8),Text(s.body),InfoBox('الدعاء',s.dua,AppColors.softGreen,center:true),InfoBox('💡 نصيحة',s.tip,AppColors.softGold),InfoBox('⚠️ خطأ شائع',s.error,AppColors.softRed)])),if(s.simulation!=null)...[const SizedBox(height:10),CounterCard(type:s.simulation!)],const SizedBox(height:10),PrimaryButton(st.step<6?'تمّت هذه الخطوة ← التالية':'أتممت العمرة، تقبّل الله',onTap:()=>st.change((){st.done.add(st.step);if(st.step<6)st.step++;})),const Padding(padding:EdgeInsets.all(10),child:Text('محتوى إرشادي، وللفتوى راجع أهل العلم.',textAlign:TextAlign.center,style:TextStyle(fontSize:12,color:AppColors.muted))) ]))]));}}
class InfoBox extends StatelessWidget{final String title,text;final Color color;final bool center;const InfoBox(this.title,this.text,this.color,{super.key,this.center=false});@override Widget build(BuildContext c)=>Container(width:double.infinity,margin:const EdgeInsets.only(top:8),padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:color,borderRadius:BorderRadius.circular(14)),child:Column(crossAxisAlignment:center?CrossAxisAlignment.center:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),Text(text,textAlign:center?TextAlign.center:null,style:TextStyle(fontSize:center?20:15,height:center?1.8:1.4,color:AppColors.ink))]));}
class CounterCard extends StatelessWidget{final String type;const CounterCard({super.key,required this.type});@override Widget build(BuildContext c){final st=AppScope.of(c),n=type=='tawaf'?st.tawaf:st.sai;return AppCard(child:Column(children:[const Align(alignment:Alignment.centerRight,child:Text('محاكاة تفاعلية',style:TextStyle(color:Color(0xFF7A5B12),fontWeight:FontWeight.w800))),SizedBox(height:180,child:CustomPaint(size:const Size(double.infinity,180),painter:type=='tawaf'?TawafPainter(n):SaiPainter(n))),Text('$n / 7',style:const TextStyle(fontSize:52,fontWeight:FontWeight.w800,color:AppColors.gold)),Text(n>=7?'أتممت 7 أشواط 🎉':type=='tawaf'?'اضغط بعد كل شوط تكمله':(n.isEven?'أنت عند الصفا: اتجه للمروة':'أنت عند المروة: اتجه للصفا')),const SizedBox(height:8),PrimaryButton(type=='tawaf'?'أتممت شوطًا':'وصلت الطرف الآخر',onTap:n>=7?null:()=>st.change(()=>type=='tawaf'?st.tawaf++:st.sai++)),const SizedBox(height:8),PrimaryButton('إعادة العدّاد',outline:true,onTap:()=>st.change(()=>type=='tawaf'?st.tawaf=0:st.sai=0))]));}}
class TawafPainter extends CustomPainter{final int n;TawafPainter(this.n);@override void paint(Canvas c,Size s){final p=Paint()..style=PaintingStyle.stroke..strokeWidth=12..color=AppColors.line;final center=Offset(s.width/2,s.height/2);c.drawCircle(center,58,p);p.color=AppColors.gold;c.drawArc(Rect.fromCircle(center:center,radius:58),-1.57,6.283*(n.clamp(0,7)/7),false,p);c.drawRect(Rect.fromCenter(center:center,width:38,height:38),Paint()..color=Colors.black);c.drawRect(Rect.fromCenter(center:Offset(center.dx,center.dy-8),width:38,height:4),Paint()..color=AppColors.gold);}@override bool shouldRepaint(covariant TawafPainter old)=>old.n!=n;}
class SaiPainter extends CustomPainter{final int n;SaiPainter(this.n);@override void paint(Canvas c,Size s){final y=s.height/2;c.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(25,y-5,s.width-50,10),const Radius.circular(5)),Paint()..color=AppColors.line);c.drawRect(Rect.fromLTWH(s.width*.37,y-5,s.width*.26,10),Paint()..color=const Color(0xFF2E9D6F));final x=n.isEven?30.0:s.width-30;c.drawCircle(Offset(x,y),10,Paint()..color=AppColors.green);}@override bool shouldRepaint(covariant SaiPainter old)=>old.n!=n;}
